<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use App\Models\Place;use App\Models\SponsorshipCampaign;use Illuminate\Contracts\View\View;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\Validation\Rule;
class SponsorshipController extends Controller {public function index():View{return view('admin.sponsorships',['campaigns'=>SponsorshipCampaign::with('place')->latest()->get(),'places'=>Place::where('publication_status','published')->orderBy('name')->get()]);}public function store(Request $request):RedirectResponse{$data=$this->validated($request);$data['created_by']=$request->user()->id;SponsorshipCampaign::create($data);return back()->with('campaign_status','Campaña creada. La publicidad permanece separada del ranking.');}private function validated(Request $request):array{return $request->validate(['place_id'=>['nullable','exists:places,id'],'sponsor_name'=>['required','string','max:191'],'title'=>['required','string','max:120'],'description'=>['required','string','max:500'],'destination_url'=>['required','url:http,https','max:500'],'starts_on'=>['required','date'],'ends_on'=>['required','date','after_or_equal:starts_on'],'status'=>['required',Rule::in(['draft','active','paused','finished'])]]);}}
